import type * as ReactNS from "react";

import { hostAccentForMode, useHostTheme } from "./hostTheme";

const host = window.QwenPaw.host;

/** hex（#rgb/#rrggbb）+ alpha → rgba() 串。非法 hex 回退现行橙。 */
function accentTint(accent: string, alpha: number): string {
  const m =
    /^#([0-9a-fA-F]{6})$/.exec(accent) ?? /^#([0-9a-fA-F]{3})$/.exec(accent);
 if (!m) return `color-mix(in srgb, var(--app-accent, #FF7F16) ${(alpha * 100).toFixed(1)}%, transparent)`;
  let h = m[1];
  if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}

/** 主题颜色（深色模式适配）。antd 组件自身由宿主 ConfigProvider 控制；
 * 这里只管插件内联样式的硬编码颜色。 */
export interface ThemeColors {
  mode: "light" | "dark";
  /** 页面/卡片背景。 */
  bg: string;
  cardBg: string;
  /** 主文字 / 次级文字。 */
  text: string;
  textSecondary: string;
  /** 边框与分隔线。 */
  border: string;
  /** 他人气泡底 / 自己的气泡底。 */
  bubbleOther: string;
  bubbleMine: string;
  /** hover 底色。 */
  hoverBg: string;
  /** 弹层/悬浮工具条背景。 */
  popoverBg: string;
  /** 工具消息底色。 */
  toolBg: string;
  /** 主色浅底（accent 10% tint；管理页 rail 选中行等）。 */
  accentBg: string;
}

const LIGHT: ThemeColors = {
  mode: "light",
  bg: "#ffffff",
  // 卡片微透——白 72% 让宿主米白底微透，
  // 层次感增强；宿主底为纯色，文字对比不受影响。
  cardBg: "rgba(255,255,255,0.72)",
  text: "rgba(0,0,0,0.88)",
  textSecondary: "#888",
  border: "rgba(0,0,0,0.08)",
  bubbleOther: "rgba(0,0,0,0.04)",
 bubbleMine: "color-mix(in srgb, var(--app-accent, #FF7F16) 8%, transparent)",
  hoverBg: "rgba(0,0,0,0.03)",
  popoverBg: "#ffffff",
  toolBg: "rgba(0,0,0,0.03)",
  accentBg: "color-mix(in srgb, var(--app-accent, #FF7F16) 10%, transparent)",
};

const DARK: ThemeColors = {
  mode: "dark",
  bg: "#141414",
  // 卡片透黑——白 5% 对黑底=比页面
  // #141414 微亮一档的半透明卡，层次靠亮度差而非实色块。
  cardBg: "rgba(255,255,255,0.05)",
  text: "rgba(255,255,255,0.88)",
  textSecondary: "#8c8c8c",
  border: "rgba(255,255,255,0.12)",
  bubbleOther: "rgba(255,255,255,0.08)",
 bubbleMine: "color-mix(in srgb, var(--app-accent, #FF7F16) 18%, transparent)",
  hoverBg: "rgba(255,255,255,0.06)",
  popoverBg: "#2a2a2a",
  toolBg: "rgba(255,255,255,0.06)",
  accentBg: "color-mix(in srgb, var(--app-accent, #FF7F16) 10%, transparent)",
};

/** 读取宿主主题（host.useTheme，插件组件内调用）。
 * 自己的气泡底（bubbleMine）= 宿主主色 tint（QwenPaw ≥2.2.2 跟随；
 * 旧宿主/取不到 = 内置橙，行为不变）。 */
export function useThemeColors(): ThemeColors {
  let mode: string = "light";
  try {
    if (typeof host.useTheme === "function") {
      mode = host.useTheme() === "dark" ? "dark" : "light";
    }
  } catch {
    mode = "light";
  }
  const dark = mode === "dark";
  const hostT = useHostTheme();
  const accent = hostAccentForMode(hostT, dark ? "dark" : "light");
  return {
    ...(dark ? DARK : LIGHT),
    bubbleMine: accentTint(accent, dark ? 0.18 : 0.08),
    accentBg: accentTint(accent, 0.10),
  };
}

/** 非组件上下文（事件回调等）读主题（不响应式，按需调用）。 */
export function readThemeColors(): ThemeColors {
  let mode: string = "light";
  try {
    const h = (window as unknown as { QwenPaw?: { host?: { useTheme?: () => string } } })
      .QwenPaw?.host;
    if (h && typeof h.useTheme === "function") {
      mode = h.useTheme() === "dark" ? "dark" : "light";
    }
  } catch {
    mode = "light";
  }
  return mode === "dark" ? DARK : LIGHT;
}

export type { ReactNS };
